import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"History","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/history.md","filePath":"user-guide/settings/history.md","lastUpdated":1786537234000}'),s={name:"user-guide/settings/history.md"};function i(n,e,l,d,h,c){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h1><p>Two tabs, each independent: <strong>Search History</strong> and <strong>Keyword History</strong>.</p><h2 id="search-history" tabindex="-1">Search History <a class="header-anchor" href="#search-history" aria-label="Permalink to &quot;Search History&quot;">​</a></h2><p>Tracks results you&#39;ve actually opened, so they can be prioritized the next time you search for something similar.</p><p>Search History remembers both the opened path and the query that led to it. A later fuzzy match against that recorded query can recall and prioritize the existing path in the quick, inline, and full search windows—for example, opening <code>BCompare.exe</code> with <code>bcomp</code> lets <code>bc</code> bring it back near the top. Inline search keeps matches inside the active folder under <strong>Current Folder</strong> and places the rest under <strong>Global Search</strong>; missing paths are ignored and duplicate paths appear only once.</p><ul><li><strong>Enable History</strong> checkbox — turns tracking on/off; existing entries are kept even if you disable it, they&#39;re just no longer added to.</li><li><strong>Search box</strong> — filters the visible history list by keyword.</li><li>Each entry can be deleted individually, or all at once with <strong>Clear All History</strong>.</li></ul><h2 id="keyword-history" tabindex="-1">Keyword History <a class="header-anchor" href="#keyword-history" aria-label="Permalink to &quot;Keyword History&quot;">​</a></h2><p>Tracks the raw text you&#39;ve typed into the quick window&#39;s search box (not what you opened), so you can cycle back through recent queries with the <a href="./../hotkeys.html#global-hotkeys">keyword history hotkeys</a> (<code>Alt+Up</code> / <code>Alt+Down</code> by default).</p><ul><li>Same <strong>Enable History</strong> toggle, search filter, per-entry delete, and <strong>Clear All History</strong> button, scoped to keywords instead of opened results.</li></ul>',9)])])}const p=t(s,[["render",i]]);export{u as __pageData,p as default};
